PRAGMA journal_mode=DELETE;
BEGIN;
CREATE TABLE [Area] ([OID] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, [Name] nvarchar(100), [OptimisticLockField] int, [GCRecord] int);
CREATE TABLE [AuditDataItemPersistent] ([Oid] char(36) NOT NULL, [UserName] nvarchar(100), [ModifiedOn] datetime, [OperationType] nvarchar(100), [Description] text, [AuditedObject] char(36), [OldObject] char(36), [NewObject] char(36), [OldValue] text, [NewValue] text, [PropertyName] nvarchar(100), [UserId] nvarchar(100), [OptimisticLockField] int, [GCRecord] int, primary key ([Oid]));
CREATE TABLE [AuditedObjectWeakReference] ([Oid] char(36) NOT NULL, [GuidId] char(36), [IntId] int, [DisplayName] nvarchar(250), primary key ([Oid]));
CREATE TABLE [Company] ([OID] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, [Name] nvarchar(100), [OptimisticLockField] int, [GCRecord] int);
CREATE TABLE [Contact] ([Oid] char(36) NOT NULL, [Title] nvarchar(100), [Company] int, [PropertyName] double, primary key ([Oid]));
CREATE TABLE [ControlSystem] ([OID] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, [Name] nvarchar(100), [Type] int, [Description] nvarchar(100), [OptimisticLockField] int, [GCRecord] int);
CREATE TABLE [ControlSystemType] ([OID] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, [Name] nvarchar(100), [Description] nvarchar(100), [OptimisticLockField] int, [GCRecord] int);
CREATE TABLE [DailySchedule] ([OID] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, [AssignedTo] char(36), [Date] datetime, [ScheduledLoop] int, [OptimisticLockField] int, [GCRecord] int);
CREATE TABLE [Drawing] ([OID] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, [File] char(36), [Number] nvarchar(100), [Description] nvarchar(100), [OptimisticLockField] int, [GCRecord] int, [ObjectType] int);
CREATE TABLE [Event] ([Oid] char(36) NOT NULL, [ResourceIds] text, [RecurrencePattern] char(36), [Subject] nvarchar(250), [Description] text, [StartOn] datetime, [EndOn] datetime, [AllDay] bit, [Location] nvarchar(100), [Label] int, [Status] int, [Type] int, [RemindIn] double, [ReminderInfoXml] nvarchar(200), [AlarmTime] datetime, [IsPostponed] bit, [RecurrenceInfoXml] text, [OptimisticLockField] int, [GCRecord] int, [ObjectType] int, [Item] int, [Schedule] char(36), [CheckDate] datetime, primary key ([Oid]));
CREATE TABLE [FileData] ([Oid] char(36) NOT NULL, [size] int, [FileName] nvarchar(260), [Content] image, [OptimisticLockField] int, [GCRecord] int, primary key ([Oid]));
CREATE TABLE [FileLinkObject] ([Oid] char(36) NOT NULL, [FileName] nvarchar(260), [FullName] text, [FileExists] bit, [OptimisticLockField] int, [GCRecord] int, primary key ([Oid]));
CREATE TABLE [IOType] ([OID] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, [Name] nvarchar(100), [Description] nvarchar(100), [OptimisticLockField] int, [GCRecord] int);
CREATE TABLE [Instrument] ([OID] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, [DataSheet] char(36), [TagNumber] nvarchar(100), [PID] int, [JunctionBox] int, [LocationPlan] int, [Calibration] nvarchar(100), [IOType] int, [Loop] int, [LoopDrawing] int, [ControlSystem] int, [InstrumentType] int, [ServiceDescription] nvarchar(100), [ResponsibleCompany] int, [OptimisticLockField] int, [GCRecord] int);
CREATE TABLE [InstrumentType] ([OID] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, [Name] nvarchar(100), [OptimisticLockField] int, [GCRecord] int);
CREATE TABLE [JobInfo] ([OID] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, [Number] nvarchar(100), [Description] nvarchar(100), [ClientName] nvarchar(100), [ClientJobNumber] nvarchar(100), [OptimisticLockField] int, [GCRecord] int);
CREATE TABLE [JunctionBox] ([OID] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, [Number] nvarchar(100), [OptimisticLockField] int, [GCRecord] int);
CREATE TABLE [LocationPlan] ([OID] int NOT NULL, primary key ([OID]));
CREATE TABLE [Loop] ([OID] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, [LoopNumber] nvarchar(100), [Description] nvarchar(100), [LoopCheckStatus] int, [TargetLoopCheckDate] datetime, [LoopFolderReceived] bit, [LoopProvider] int, [OptimisticLockField] int, [GCRecord] int);
CREATE TABLE [LoopCheck] ([Oid] char(36) NOT NULL, [EndOn] datetime, [StartOn] datetime, [OptimisticLockField] int, [GCRecord] int, primary key ([Oid]));
CREATE TABLE [LoopCheckStatus] ([OID] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, [Description] nvarchar(100), [SortOrder] smallint, [OptimisticLockField] int, [GCRecord] int);
CREATE TABLE [LoopDrawing] ([OID] int NOT NULL, primary key ([OID]));
CREATE TABLE [LoopLoops_AreaAreas] ([Areas] int, [Loops] int, [OID] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, [OptimisticLockField] int);
CREATE TABLE [ModelDifference] ([Oid] char(36) NOT NULL, [UserId] nvarchar(100), [ContextId] nvarchar(100), [Version] int, [OptimisticLockField] int, [GCRecord] int, primary key ([Oid]));
