CREATE TABLE [PID] ([OID] int NOT NULL, primary key ([OID]));
CREATE TABLE [PermissionPolicyActionPermissionObject] ([Oid] char(36) NOT NULL, [ActionId] nvarchar(100), [Role] char(36), [OptimisticLockField] int, [GCRecord] int, primary key ([Oid]));
