CREATE TABLE [PermissionPolicyTypePermissionsObject] ([Oid] char(36) NOT NULL, [Role] char(36), [TargetType] text, [ReadState] int, [WriteState] int, [CreateState] int, [DeleteState] int, [NavigateState] int, [OptimisticLockField] int, [GCRecord] int, primary key ([Oid]));
